```sql
-- Standard View (Virtual, runs live)
CREATE VIEW ActiveUsers AS
SELECT id, name FROM users WHERE status = 'active';

-- Materialized View (PostgreSQL syntax - Physically stored)
CREATE MATERIALIZED VIEW MonthlySales AS
SELECT month, sum(amount) FROM sales GROUP BY month;
-- Must be refreshed later via: REFRESH MATERIALIZED VIEW MonthlySales;
```

```sql
-- Function: Used inside a SELECT query
SELECT EmployeeName, dbo.CalculateTax(Salary) FROM Employees;

-- Stored Procedure: Executed independently to run logic
EXECUTE ProcessMonthlyPayroll @Month = 'May';
```

```sql
-- CTE: Dies immediately after the SELECT statement
WITH HighEarners AS (SELECT * FROM Employees WHERE Salary > 100k)
SELECT * FROM HighEarners;

-- Temp Table: Persists in the session, can be indexed and queried repeatedly
SELECT * INTO #HighEarners FROM Employees WHERE Salary > 100k;
CREATE INDEX IX_Temp_Salary ON #HighEarners(Salary);
SELECT * FROM #HighEarners;
```

```sql
-- THE PROBLEM (Application code running in a loop):
-- 1 query: SELECT * FROM Orders;
-- N queries: foreach(order in orders) { SELECT * FROM OrderItems WHERE OrderId = order.Id; }

-- THE FIX (One single database call):
SELECT o.OrderId, o.OrderDate, i.ItemName, i.Price
FROM Orders o
INNER JOIN OrderItems i ON o.OrderId = i.OrderId;
```

```sql
-- BAD: Breaks index usage (Table Scan)
SELECT name FROM employees WHERE SUBSTRING(name, 1, 1) = 'A';

-- GOOD: Preserves index usage (Index Seek)
SELECT name FROM employees WHERE name LIKE 'A%';
```
